const results = await Promise.allSettled([
  tools.exec_command({cmd:"rtk entire activity",sandbox_permissions:"require_escalated",justification:"May I query Entire's activity service to compare the cloud report with the local checkpoint records?",prefix_rule:["rtk","entire","activity"],yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"rtk entire checkpoint explain f4ce5f22d15afddc42851fbcf336e7f2cfd9abc1 && rtk entire checkpoint tokens f4ce5f22d15afddc42851fbcf336e7f2cfd9abc1 --json",yield_time_ms:10000,max_output_tokens:2500}),
  tools.exec_command({cmd:"rtk proxy rg -n 'e2fe6504-b7f2-430b-a234-1e8197320f97|remote checkpoint enumeration failed|push_sessions|push_checkpoints' .entire/logs/entire.log | tail -35",yield_time_ms:10000,max_output_tokens:2500})
]); for (const x of results) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"rtk git show-ref | rg 'entire|checkpoint' | tail -30"}),
  tools.exec_command({cmd:"rtk git ls-remote origin 'refs/entire/checkpoints/v1/*'",sandbox_permissions:"require_escalated",justification:"May I check the remote checkpoint refs, using Entire's git-refs namespace, to confirm whether this repository has uploaded its checkpoints?",prefix_rule:["rtk","git","ls-remote"],yield_time_ms:10000,max_output_tokens:1000}),
  tools.exec_command({cmd:"rtk entire checkpoint list --json",sandbox_permissions:"require_escalated",justification:"May I compare this branch's committed checkpoint list with Entire's remote checkpoint store?",prefix_rule:["rtk","entire","checkpoint","list"],yield_time_ms:10000,max_output_tokens:1500})
]); for (const x of results) text(x.status === "fulfilled" ? x.value.output : String(x.reason));
